import heapq

def largest_values(values, k):
    if type(k) is not int or k < 0:
        raise ValueError("expected nonnegative integer k")
    heap = []
    for value in values:
        # Precondition: mutually comparable integer values.
        if k == 0:
            continue
        if len(heap) < k:
            heapq.heappush(heap, value)
        elif value > heap[0]:
            heapq.heapreplace(heap, value)
    return sorted(heap, reverse=True)

print(largest_values([5, 1, 5, 3, 8], 3))
print(largest_values([2, 1], 5))
print(largest_values([2, 1], 0))

import heapq

def merge_sorted_streams(streams):
    # Precondition: each stream is ascending and finite, with comparable integers.
    iterators = [iter(stream) for stream in streams]
    heap = []
    for stream_id, iterator in enumerate(iterators):
        first = next(iterator, None)
        if first is not None:
            heapq.heappush(heap, (first, stream_id))
    while heap:
        value, stream_id = heapq.heappop(heap)
        yield value
        following = next(iterators[stream_id], None)
        if following is not None:
            heapq.heappush(heap, (following, stream_id))

print(list(merge_sorted_streams([[1, 4], [], [1, 2, 5]])))

