def valid_intervals(intervals):
    if not 1 <= len(intervals) <= 100000:
        raise ValueError('invalid interval count')
    if any((type(s) is not int or type(e) is not int or (not 0 <= s < e <= 10 ** 9) for (s, e) in intervals)):
        raise ValueError('invalid half-open interval')

def rooms_needed(intervals):
    import heapq
    valid_intervals(intervals)
    active = []
    peak = 0
    for (start, end) in sorted(intervals):
        while active and active[0] <= start:
            heapq.heappop(active)
        heapq.heappush(active, end)
        peak = max(peak, len(active))
    return [str(peak)]

print(rooms_needed([(0, 3), (1, 2), (2, 4), (4, 5)]))
print(rooms_needed([(1, 2), (2, 3)]))

