def top_k(k, a):
    """Count first; larger (count, -value) means a better entry."""
    import heapq
    counts = {}
    for value in a:
        counts[value] = counts.get(value, 0) + 1
    best = []
    for (value, count) in counts.items():
        quality = (count, -value)
        if len(best) < k:
            heapq.heappush(best, quality)
        elif quality > best[0]:
            heapq.heapreplace(best, quality)
    return [f'{-neg_value} {count}' for (count, neg_value) in sorted(best, reverse=True)]

print(top_k(2, [5, 3, 5, 1, 3, 5, 3, 9]))
print(top_k(3, [2, 2, -1, -1]))

