import heapq

def kth_largest(k, stream):
    heap = []
    lines = []
    for value in stream:
        if len(heap) < k:
            heapq.heappush(heap, value)
        elif value > heap[0]:
            heapq.heapreplace(heap, value)
        lines.append(str(heap[0]) if len(heap) == k else '-1')
    return lines

print(*kth_largest(2, [5, 5, 3, 8]), sep='\n')

