def running_median(prices):
    (lower, upper) = ([], [])
    lines = []
    for price in prices:
        if not lower or price <= -lower[0]:
            heapq.heappush(lower, -price)
        else:
            heapq.heappush(upper, price)
        if len(lower) > len(upper) + 1:
            heapq.heappush(upper, -heapq.heappop(lower))
        elif len(upper) > len(lower):
            heapq.heappush(lower, -heapq.heappop(upper))
        twice = -2 * lower[0] if len(lower) > len(upper) else -lower[0] + upper[0]
        lines.append(f'{twice // 2}.{(5 if twice % 2 else 0)}')
    return lines

print(*running_median([5, 2, 8, 2]), sep='\n')
